import{_ as e,c as l,o as i,ak as r}from"./chunks/framework.CtX3_w5e.js";const m=JSON.parse('{"title":"英伟达-黄仁勋之芯","description":"","frontmatter":{"title":"英伟达-黄仁勋之芯","hugoSource":"books/英伟达-黄仁勋之芯.md","outline":[1,6]},"headers":[],"relativePath":"Books/2026-11-17-英伟达-黄仁勋之芯.md","filePath":"Books/2026-11-17-英伟达-黄仁勋之芯.md","lastUpdated":1794887319000}'),h={name:"Books/2026-11-17-英伟达-黄仁勋之芯.md"};function n(d,a,t,o,s,c){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="黄仁勋-英伟达之芯" tabindex="-1">黄仁勋-英伟达之芯 <a class="header-anchor" href="#黄仁勋-英伟达之芯" aria-label="Permalink to “黄仁勋-英伟达之芯”">​</a></h1><h2 id="第1章-求学生涯" tabindex="-1">第1章 求学生涯 <a class="header-anchor" href="#第1章-求学生涯" aria-label="Permalink to “第1章 求学生涯”">​</a></h2><h2 id="第2章-职涯早期" tabindex="-1">第2章 职涯早期 <a class="header-anchor" href="#第2章-职涯早期" aria-label="Permalink to “第2章 职涯早期”">​</a></h2><h2 id="第3章-从餐厅起步的nvidia" tabindex="-1">第3章 从餐厅起步的Nvidia <a class="header-anchor" href="#第3章-从餐厅起步的nvidia" aria-label="Permalink to “第3章 从餐厅起步的Nvidia”">​</a></h2><h2 id="第4章-英伟达遭遇绝境" tabindex="-1">第4章 英伟达遭遇绝境 <a class="header-anchor" href="#第4章-英伟达遭遇绝境" aria-label="Permalink to “第4章 英伟达遭遇绝境”">​</a></h2><h2 id="第5章-咸鱼翻身" tabindex="-1">第5章 咸鱼翻身 <a class="header-anchor" href="#第5章-咸鱼翻身" aria-label="Permalink to “第5章 咸鱼翻身”">​</a></h2><h2 id="第6章-新机器时代曙光初现" tabindex="-1">第6章 新机器时代曙光初现 <a class="header-anchor" href="#第6章-新机器时代曙光初现" aria-label="Permalink to “第6章 新机器时代曙光初现”">​</a></h2><h2 id="第7章-死亡竞赛" tabindex="-1">第7章 死亡竞赛 <a class="header-anchor" href="#第7章-死亡竞赛" aria-label="Permalink to “第7章 死亡竞赛”">​</a></h2><h2 id="第8章-游戏玩家拯救英伟达" tabindex="-1">第8章 游戏玩家拯救英伟达 <a class="header-anchor" href="#第8章-游戏玩家拯救英伟达" aria-label="Permalink to “第8章 游戏玩家拯救英伟达”">​</a></h2><h2 id="第9章-光速之道" tabindex="-1">第9章 光速之道 <a class="header-anchor" href="#第9章-光速之道" aria-label="Permalink to “第9章 光速之道”">​</a></h2><h2 id="第10章-同频共振" tabindex="-1">第10章 同频共振 <a class="header-anchor" href="#第10章-同频共振" aria-label="Permalink to “第10章 同频共振”">​</a></h2><h2 id="第11章-范式转变的时刻" tabindex="-1">第11章 范式转变的时刻 <a class="header-anchor" href="#第11章-范式转变的时刻" aria-label="Permalink to “第11章 范式转变的时刻”">​</a></h2><h2 id="第12章-千载难逢的机会" tabindex="-1">第12章 千载难逢的机会 <a class="header-anchor" href="#第12章-千载难逢的机会" aria-label="Permalink to “第12章 千载难逢的机会”">​</a></h2><h2 id="第13章-由机器引领的时代" tabindex="-1">第13章 由机器引领的时代 <a class="header-anchor" href="#第13章-由机器引领的时代" aria-label="Permalink to “第13章 由机器引领的时代”">​</a></h2><ul><li>克里泽夫斯基：辛顿在多伦多大学时的学生</li><li>因为无法解释神经网络的计算过程，学术界不认可这种方法</li><li>辛顿给<strong>苏茨克弗</strong>和<strong>克里泽夫斯基</strong>布置了一项艰巨的任务：利用英伟达的GPU训练计算机学会图像识别</li><li>卡坦扎罗 2011年加入英伟达 <ul><li>cuDNN cuda deep neural network</li></ul></li><li>矩阵乘法</li><li>优秀的神经网络软件应该注重速度而不是精度</li><li>马克思与黄仁勋的分歧 <ul><li>马斯克认为，先进的人工智能可能带来灭绝级威胁。这一观点得到了包括辛顿和苏茨克弗在内的大批技术专家的认同，他们还是最初那篇关于AlexNet的论文的合著者。然而黄仁勋完全不这么认为。他竟觉得人工智能毫无风险，真是令我吃惊。</li></ul></li></ul><h2 id="第14章-ai行业的佼佼者" tabindex="-1">第14章 AI行业的佼佼者 <a class="header-anchor" href="#第14章-ai行业的佼佼者" aria-label="Permalink to “第14章 AI行业的佼佼者”">​</a></h2><ul><li>2016年，英伟达的股价飙升了224%，这让黄仁勋重获荣光，再度跻身亿万富翁行列。不过，在当年的标准普尔500指数中，表现最抢眼的股票并非英伟达，而是其长期竞争对手AMD，其股价涨幅高达309%。黄仁勋并不甘心位居次席。</li><li>Omniverse</li></ul><h2 id="第15章-ai工厂" tabindex="-1">第15章 AI工厂 <a class="header-anchor" href="#第15章-ai工厂" aria-label="Permalink to “第15章 AI工厂”">​</a></h2><ul><li><strong>乌斯科雷特</strong>把这套学习机制命名为“自注意力”</li></ul><h2 id="第16章-全球最具价值的半导体企业" tabindex="-1">第16章 全球最具价值的半导体企业 <a class="header-anchor" href="#第16章-全球最具价值的半导体企业" aria-label="Permalink to “第16章 全球最具价值的半导体企业”">​</a></h2><ul><li>在2018年的GTC大会上，黄仁勋指出，在短短5年内，英伟达的GPU处理速度提升了25倍，这一成绩远超摩尔定律的预测。接着，他展示了一张图，这张图显示在2012年的显卡上需要一周的时间才能训练出AlexNet，而在他推出的新款计算机DGX-2上则仅需18分钟就能完成训练。</li><li>2020年7月，英伟达的市值终于超越了英特尔。没过多久，英伟达的市值又超越了AMD。</li></ul><h2 id="第17章-这个时代最重要的科技公司" tabindex="-1">第17章 这个时代最重要的科技公司 <a class="header-anchor" href="#第17章-这个时代最重要的科技公司" aria-label="Permalink to “第17章 这个时代最重要的科技公司”">​</a></h2><h2 id="第18章-人类需要更多智慧" tabindex="-1">第18章 人类需要更多智慧 <a class="header-anchor" href="#第18章-人类需要更多智慧" aria-label="Permalink to “第18章 人类需要更多智慧”">​</a></h2><h2 id="第19章-更多电力更大算力" tabindex="-1">第19章 更多电力更大算力 <a class="header-anchor" href="#第19章-更多电力更大算力" aria-label="Permalink to “第19章 更多电力更大算力”">​</a></h2><h2 id="第20章-地球上最重要的股票" tabindex="-1">第20章 地球上最重要的股票 <a class="header-anchor" href="#第20章-地球上最重要的股票" aria-label="Permalink to “第20章 地球上最重要的股票”">​</a></h2><h2 id="第21章-向理性本身发起挑战" tabindex="-1">第21章 向理性本身发起挑战 <a class="header-anchor" href="#第21章-向理性本身发起挑战" aria-label="Permalink to “第21章 向理性本身发起挑战”">​</a></h2><h2 id="第22章-深不见底的恐惧" tabindex="-1">第22章 深不见底的恐惧 <a class="header-anchor" href="#第22章-深不见底的恐惧" aria-label="Permalink to “第22章 深不见底的恐惧”">​</a></h2><h2 id="第23章-思考机器" tabindex="-1">第23章 思考机器 <a class="header-anchor" href="#第23章-思考机器" aria-label="Permalink to “第23章 思考机器”">​</a></h2>',28)])])}const f=e(h,[["render",n]]);export{m as __pageData,f as default};
